namespace {

static bool wait_event_yielding(cudaEvent_t event)
{
    if (event == nullptr) {
        return false;
    }
    cudaError_t status;
    while ((status = cudaEventQuery(event)) == cudaErrorNotReady) {
        sched_yield();
    }
    return status == cudaSuccess;
}

